"""Ultralytics YOLO adapter; output remains provider-neutral until normalization."""

from __future__ import annotations

from importlib.metadata import version
import logging
import os
from pathlib import Path

from virvision.perception.base import ProviderInfo, RawObject
from virvision.perception.device import resolve_device, synchronize

from .common import artifact

LOG = logging.getLogger("virvision.perception")


class UltralyticsDetector:
    def __init__(
        self,
        *,
        model: str,
        confidence: float = 0.25,
        iou: float = 0.45,
        device: str = "auto",
        max_objects: int = 100,
        image_size: int = 640,
    ):
        self.model_spec = model
        self.confidence = confidence
        self.iou = iou
        self.requested_device = device
        self.max_objects = max_objects
        self.image_size = image_size
        self._model = None
        self._device = "unresolved"
        self._resolved_model_path: Path | None = None

    @property
    def info(self) -> ProviderInfo:
        artifacts = ()
        if self._resolved_model_path is not None and self._resolved_model_path.is_file():
            artifacts = (artifact(self._resolved_model_path),)
        return ProviderInfo(
            "ultralytics",
            self.model_spec,
            self.requested_device,
            self._device,
            version("ultralytics"),
            artifacts,
        )

    def load(self) -> None:
        if self._model is not None:
            return
        model_path = Path(self.model_spec).expanduser()
        looks_like_path = model_path.is_absolute() or model_path.parent != Path(".")
        if looks_like_path and not model_path.is_file():
            raise FileNotFoundError(
                f"YOLO model weights were not found: {model_path.resolve()}. "
                "Run scripts/fetch_vision_models.py or set perception.detector.model."
            )
        config_root = (
            model_path.parent if looks_like_path else Path(".cache/ultralytics")
        ).resolve()
        config_dir = config_root / "config"
        # platformdirs appends "Ultralytics" to YOLO_CONFIG_DIR on Windows.
        (config_dir / "Ultralytics").mkdir(parents=True, exist_ok=True)
        os.environ.setdefault("YOLO_CONFIG_DIR", str(config_dir))
        try:
            from ultralytics import YOLO, settings
        except ImportError as exc:
            raise ImportError(
                'Ultralytics detector is unavailable. Install with: pip install -e ".[vision]"'
            ) from exc
        settings.update(
            {
                "sync": False,
                "clearml": False,
                "comet": False,
                "dvc": False,
                "mlflow": False,
                "raytune": False,
                "wandb": False,
                "tensorboard": False,
            }
        )
        self._device = resolve_device(self.requested_device)
        source = str(model_path.resolve()) if looks_like_path else self.model_spec
        self._model = YOLO(source)
        checkpoint = getattr(self._model, "ckpt_path", None)
        candidate = Path(checkpoint) if checkpoint else model_path
        self._resolved_model_path = candidate.resolve() if candidate.is_file() else None
        LOG.info(
            "detector loaded: backend=ultralytics model=%s device=%s", self.model_spec, self._device
        )

    def detect(self, image) -> tuple[RawObject, ...]:
        self.load()
        synchronize(self._device)
        results = self._model.predict(
            source=image.image,
            conf=self.confidence,
            iou=self.iou,
            device=self._device,
            max_det=self.max_objects,
            imgsz=self.image_size,
            verbose=False,
            save=False,
        )
        synchronize(self._device)
        if len(results) != 1:
            raise RuntimeError(f"Detector returned {len(results)} results for one image")
        result = results[0]
        if result.boxes is None:
            return ()
        boxes = result.boxes.xyxy.detach().cpu().tolist()
        confidences = result.boxes.conf.detach().cpu().tolist()
        classes = result.boxes.cls.detach().cpu().tolist()
        rows = []
        for box, confidence, class_id in zip(boxes, confidences, classes, strict=True):
            rows.append(
                RawObject(
                    str(result.names[int(class_id)]),
                    float(confidence),
                    tuple(float(v) for v in box),
                )
            )
        return tuple(rows)
